package engine_test

import (
	"log/slog"
	"testing"

	"github.com/acityonmars/martian-robots/internal/engine"
)

func Test_Robot_String_Formats_Position_Orientation_And_Lost(t *testing.T) {
	t.Run("on grid", func(t *testing.T) {
		robot := engine.Robot{Pos: engine.Position{X: 1, Y: 1}, Ori: engine.East}
		if got, want := robot.String(), "1 1 E"; got != want {
			t.Errorf("String() = %q, want %q", got, want)
		}
	})

	t.Run("lost", func(t *testing.T) {
		robot := engine.Robot{Pos: engine.Position{X: 3, Y: 3}, Ori: engine.North, Lost: true}
		if got, want := robot.String(), "3 3 N LOST"; got != want {
			t.Errorf("String() = %q, want %q", got, want)
		}
	})
}

func Test_Execute_Applies_Commands_In_Order(t *testing.T) {
	plan := engine.RobotPlan{
		Robot:    &engine.Robot{Pos: engine.Position{X: 1, Y: 1}, Ori: engine.East},
		Commands: commands(t, "RFRFRFRF"), // from the spec: a full loop back to the start
		World:    newTestWorld(engine.Position{X: 5, Y: 3}),
	}

	robot, err := plan.Execute(slog.New(slog.DiscardHandler))

	if err != nil {
		t.Fatalf("Execute() error = %v", err)
	}
	if got, want := robot.String(), "1 1 E"; got != want {
		t.Errorf("robot = %q, want %q", got, want)
	}
}

func Test_Execute_Stops_Applying_Commands_Once_Robot_Is_Lost(t *testing.T) {
	plan := engine.RobotPlan{
		Robot:    &engine.Robot{Pos: engine.Position{X: 0, Y: 0}, Ori: engine.South},
		Commands: commands(t, "FRF"), // F falls off; R and F must be ignored
		World:    newTestWorld(engine.Position{X: 5, Y: 3}),
	}

	robot, err := plan.Execute(slog.New(slog.DiscardHandler))

	if err != nil {
		t.Fatalf("Execute() error = %v", err)
	}
	// Still facing S: the R after the fall was not applied.
	if got, want := robot.String(), "0 0 S LOST"; got != want {
		t.Errorf("robot = %q, want %q", got, want)
	}
}

func Test_Execute_Fails_When_Plan_Is_Incomplete(t *testing.T) {
	world := newTestWorld(engine.Position{X: 5, Y: 3})
	robot := &engine.Robot{Pos: engine.Position{X: 1, Y: 1}, Ori: engine.North}

	logger := slog.New(slog.DiscardHandler)

	t.Run("no robot", func(t *testing.T) {
		if _, err := (engine.RobotPlan{World: world}).Execute(logger); err == nil {
			t.Error("Execute() error = nil, want error")
		}
	})

	t.Run("no world", func(t *testing.T) {
		if _, err := (engine.RobotPlan{Robot: robot}).Execute(logger); err == nil {
			t.Error("Execute() error = nil, want error")
		}
	})
}
